/* ── Design system shadcn theme ─────────────────────────────────────────────────
   Drop-in theme layer: maps shadcn semantic vars onto the design
   tokens (ds-tokens.css). Import AFTER `@import "tailwindcss"` in your
   app's global stylesheet:

     @import "tailwindcss";
     @import "./ds-theme.css";

   Requires the 2 UI font faces to be loaded by your app (Geist,
   Geist Mono) and exposed as --font-geist-sans / --font-geist-mono. Registries
   can't ship fonts — wire them in your layout.

   Scoped to `.ds` so `bg-primary`, `text-foreground`, etc. only carry
   design-system values inside a `.ds` region; the rest of the page is untouched.

   IMPORTANT — background / foreground routing:
   For the `.ds` scope to work, your host `@theme` must map these two tokens
   through the semantic CSS variables, NOT to a literal colour or an intermediate
   variable defined on `:root`:

     ✅ --color-background: var(--background);   ← reads from .ds scope
     ✅ --color-foreground: var(--foreground);

     ❌ --color-background: #F1F1F3;             ← ignores .ds scope entirely
     ❌ --color-background: var(--_background);  ← same problem if --_background
                                                    is on :root, not .ds

   Same rule applies to any token you route through an rgb() pair or a --_*
   bridge variable — .ds can only override what the utility actually reads.

   Mapping decisions (see design-system/docs/DESIGN-SYSTEM.md):
   - primary   = ink (neutral-900) — the primary button is solid near-black.
   - secondary = quiet surface button (neutral-100).
   - cta       = brand blue — reserved for the one loud action per screen.
   - accent    = neutral hover surface (shadcn convention).
   - muted     = neutral surface; muted-foreground = supporting text.
   - ring      = brand blue — keyboard focus is always visible.
   - radius    = 8px. */
@import "./ds-tokens.css";

.ds {
  --background: var(--ds-neutral-50);
  --foreground: var(--ds-neutral-900);
  --card: var(--ds-neutral-100);                 /* recessed panel */
  --card-foreground: var(--ds-neutral-900);
  /* Elevation model: floating UI uses the LIGHTEST surface so it reads as
     raised above the page (see design-system/docs/elevation.md). */
  --popover: var(--ds-white);
  --popover-foreground: var(--ds-neutral-900);

  --primary: var(--ds-neutral-900);
  --primary-foreground: var(--ds-neutral-50);

  /* Secondary = quiet surface button (ranks below primary). */
  --secondary: var(--ds-neutral-100);
  --secondary-foreground: var(--ds-neutral-900);

  /* CTA = brand colour, reserved for the one loud action per screen. */
  --cta: var(--ds-brand-600);
  --cta-foreground: var(--ds-white);

  --muted: var(--ds-neutral-100);
  --muted-foreground: var(--ds-neutral-500);

  --accent: var(--ds-neutral-100);               /* hover surface */
  --accent-foreground: var(--ds-neutral-900);

  --destructive: var(--ds-danger-600);
  /* White text on the red, in BOTH modes. */
  --destructive-foreground: var(--ds-white);
  /* Red for TEXT and small marks (error labels, status squares) — not fills.
     Same as --destructive on light surfaces; lifted on dark ones. */
  --destructive-text: var(--ds-danger-600);

  /* Status marks (banner/toast tones). */
  --success: var(--ds-success-600);
  --success-text: var(--ds-success-700);
  --warning: var(--ds-warning-500);
  --warning-text: var(--ds-warning-700);

  --border: var(--ds-neutral-200);
  /* Softer hairline — nav chrome only, so the top bar edge isn't harsh. */
  --border-subtle: var(--ds-neutral-100);
  --input: var(--ds-neutral-300);                /* visible field edge */
  --ring: var(--ds-brand-500);                   /* focus ring */

  --radius: var(--ds-radius);

  background: var(--background);
  color: var(--foreground);
  font-family: var(--font-geist-sans), var(--ds-font-sans);
  letter-spacing: var(--ds-tracking);
}

/* Minimal scrollbar — scoped to .ds so the host app's scrollbars are untouched. */
.ds ::-webkit-scrollbar {
  width: 8px;
  height: 8px;
}
.ds ::-webkit-scrollbar-track {
  background: transparent;
}
.ds ::-webkit-scrollbar-thumb {
  background: var(--ds-neutral-300);
  border: 0;
  border-radius: 999px;
}
.ds ::-webkit-scrollbar-thumb:hover {
  background: var(--ds-neutral-400);
}
.ds * {
  scrollbar-width: thin;                                        /* Firefox */
  scrollbar-color: var(--ds-neutral-300) transparent;
}

/* Fully hide scroll (keeps scrolling) — opt-in for minimal regions. */
.ds .ds-no-scrollbar {
  scrollbar-width: none;
  -ms-overflow-style: none;
}
.ds .ds-no-scrollbar::-webkit-scrollbar {
  display: none;
}

/* ── Dark mode ───────────────────────────────────────────────────────────
   Two selector forms are supported:
   - `.ds.dark`  — `dark` on the same wrapper as `ds` (e.g. className="ds dark")
   - `.dark .ds` — `dark` on an ancestor (e.g. `dark` on <html>, `.ds` on a child)
   Remaps the same shadcn semantic vars onto the existing ramps — no new
   colours. */
.ds.dark,
.dark .ds {
  --background: var(--ds-neutral-950);
  --foreground: var(--ds-neutral-50);
  --card: var(--ds-neutral-900);                 /* recessed panel */
  --card-foreground: var(--ds-neutral-50);
  /* Elevation: floating UI is the LIGHTEST step, one above the page
     (bg 950 → card 900 → popover 800) so it reads as raised on dark too. */
  --popover: var(--ds-neutral-800);
  --popover-foreground: var(--ds-neutral-50);

  /* Primary inverts to a light fill so it stays the high-contrast button. */
  --primary: var(--ds-neutral-50);
  --primary-foreground: var(--ds-neutral-900);

  --secondary: var(--ds-neutral-800);
  --secondary-foreground: var(--ds-neutral-50);

  --cta: var(--ds-brand-500);
  --cta-foreground: var(--ds-white);

  --muted: var(--ds-neutral-800);
  --muted-foreground: var(--ds-neutral-400);

  --accent: var(--ds-neutral-700);               /* one step above the 800 popover so hover reads */
  --accent-foreground: var(--ds-neutral-50);

  --success: var(--ds-success-500);
  --success-text: var(--ds-success-400);
  --warning: var(--ds-warning-400);
  --warning-text: var(--ds-warning-400);

  /* Light rim, not a neutral step: dark neutrals sit too close to the
     surfaces they'd edge, so a subtle white hairline reads on every one. */
  --border: rgb(255 255 255 / 0.12);
  --border-subtle: rgb(255 255 255 / 0.07);
  --input: rgb(255 255 255 / 0.18);
  --ring: var(--ds-brand-400);

  --destructive-text: var(--ds-danger-400);      /* lifted red — reads on dark */
}

/* ── Inverse surface ─────────────────────────────────────────────────────
   Opt-in scope that flips the surface against the page: ink on the light
   page, light on the dark page. For transient UI that floats over arbitrary
   content and must never blend into it — toasts (components/ui/toast.tsx).
   Only the shadcn semantic vars are swapped; the ramps are untouched. */
.ds .ds-inverse {
  --background: var(--ds-neutral-900);
  --foreground: var(--ds-neutral-50);
  --popover: var(--ds-neutral-900);
  --popover-foreground: var(--ds-neutral-50);
  --card: var(--ds-neutral-800);
  --card-foreground: var(--ds-neutral-50);
  --primary: var(--ds-neutral-50);
  --primary-foreground: var(--ds-neutral-900);
  --secondary: var(--ds-neutral-800);
  --secondary-foreground: var(--ds-neutral-50);
  --muted: var(--ds-neutral-800);
  --muted-foreground: var(--ds-neutral-400);
  --accent: var(--ds-neutral-700);
  --accent-foreground: var(--ds-neutral-50);
  --success: var(--ds-success-500);
  --success-text: var(--ds-success-400);
  --warning: var(--ds-warning-400);
  --warning-text: var(--ds-warning-400);
  --border: rgb(255 255 255 / 0.14);
  --border-subtle: rgb(255 255 255 / 0.08);
  --input: rgb(255 255 255 / 0.2);
  --ring: var(--ds-brand-400);
  --destructive-text: var(--ds-danger-400);
  color: var(--foreground);
}
.ds.dark .ds-inverse,
.dark .ds .ds-inverse {
  --background: var(--ds-neutral-50);
  --foreground: var(--ds-neutral-900);
  --popover: var(--ds-white);
  --popover-foreground: var(--ds-neutral-900);
  --card: var(--ds-neutral-100);
  --card-foreground: var(--ds-neutral-900);
  --primary: var(--ds-neutral-900);
  --primary-foreground: var(--ds-neutral-50);
  --secondary: var(--ds-neutral-100);
  --secondary-foreground: var(--ds-neutral-900);
  --muted: var(--ds-neutral-100);
  --muted-foreground: var(--ds-neutral-500);
  --accent: var(--ds-neutral-100);
  --accent-foreground: var(--ds-neutral-900);
  --success: var(--ds-success-600);
  --success-text: var(--ds-success-700);
  --warning: var(--ds-warning-500);
  --warning-text: var(--ds-warning-700);
  --border: var(--ds-neutral-200);
  --border-subtle: var(--ds-neutral-100);
  --input: var(--ds-neutral-300);
  --ring: var(--ds-brand-500);
  --destructive-text: var(--ds-danger-600);
}

/* ----- Menu / popover motion ----------------------------------------
   Anything anchored to a trigger (dropdown, sub-menu, popover) grows
   out of that trigger rather than out of thin air: the element carries
   `origin-(--radix-...-transform-origin)`, and these keyframes supply
   the scale + fade around it.

   Radix's Presence unmounts on `animationend` and never listens for
   `transitionend`, so the exit has to be a real keyframe animation —
   a CSS transition would be skipped and the panel would vanish.

   Scale starts at 0.96, never 0: things that appear from nothing read
   as a glitch. `forwards` holds the exit's last frame so there's no
   flash of a fully-opaque panel between animationend and unmount. ----- */
@keyframes ds-menu-in {
  from { opacity: 0; transform: scale(0.96); }
  to   { opacity: 1; transform: scale(1); }
}
@keyframes ds-menu-out {
  from { opacity: 1; transform: scale(1); }
  to   { opacity: 0; transform: scale(0.96); }
}

/* Reduced motion keeps the fade — it still explains that a layer opened
   and closed — and drops the movement. Not zero, just gentler. */
@keyframes ds-menu-in-reduced {
  from { opacity: 0; }
  to   { opacity: 1; }
}
@keyframes ds-menu-out-reduced {
  from { opacity: 1; }
  to   { opacity: 0; }
}

/* ----- Modal motion -------------------------------------------------
   A dialog has no trigger to grow out of, so it stays centred and scales
   up in place — `transform-origin` is deliberately untouched here.

   The gesture is geometrically the same as a menu's (0.96 -> 1 on the same
   curve), so the dialog reuses `ds-menu-in/out` and changes only the
   duration: a modal is a much larger, unanchored surface, and the menu's
   160ms reads as a flicker on it.

   Nothing here re-states the centring `translate(-50%, -50%)`, and it must
   not: Tailwind v4 compiles `translate-x/y-*` to the standalone `translate`
   property, which the CSS `transform` in these keyframes never touches. Put
   the translate back into the keyframes and it applies on top of the utility
   — the panel opens shifted a full width/height up-left, then snaps into
   place at `animationend`.

   The scrim only ever fades, so it needs no reduced-motion variant — a
   plain opacity change is already what reduced motion would ask for. ----- */
@keyframes ds-fade-in {
  from { opacity: 0; }
  to   { opacity: 1; }
}
@keyframes ds-fade-out {
  from { opacity: 1; }
  to   { opacity: 0; }
}

/* ----- Toast timing lines --------------------------------------------
   The countdown is a clock, not a motion, so it runs linear; it pauses via
   `animation-play-state` while the toast is hovered/focused. The indeterminate
   bar marks a toast that is still working. ----- */
@keyframes ds-toast-countdown {
  from { transform: scaleX(1); }
  to   { transform: scaleX(0); }
}
@keyframes ds-toast-working {
  from { transform: translateX(-100%); }
  to   { transform: translateX(250%); }
}

/* ----- Sheet + accordion motion --------------------------------------
   A sheet slides in from the edge it docks to, on the modal durations (it's
   a large surface, like a dialog). Translating by 100% of its own size means
   it always starts fully off-screen whatever its width. The accordion grows
   to Radix's measured content height; reduced motion skips it entirely. ----- */
@keyframes ds-sheet-in-right  { from { transform: translateX(100%); } to { transform: none; } }
@keyframes ds-sheet-out-right { from { transform: none; } to { transform: translateX(100%); } }
@keyframes ds-sheet-in-left   { from { transform: translateX(-100%); } to { transform: none; } }
@keyframes ds-sheet-out-left  { from { transform: none; } to { transform: translateX(-100%); } }
@keyframes ds-sheet-in-top    { from { transform: translateY(-100%); } to { transform: none; } }
@keyframes ds-sheet-out-top   { from { transform: none; } to { transform: translateY(-100%); } }
@keyframes ds-sheet-in-bottom { from { transform: translateY(100%); } to { transform: none; } }
@keyframes ds-sheet-out-bottom{ from { transform: none; } to { transform: translateY(100%); } }

@keyframes ds-accordion-down {
  from { height: 0; }
  to   { height: var(--radix-accordion-content-height); }
}
@keyframes ds-accordion-up {
  from { height: var(--radix-accordion-content-height); }
  to   { height: 0; }
}

@theme inline {
  --color-card: var(--card);
  --color-card-foreground: var(--card-foreground);
  --color-popover: var(--popover);
  --color-popover-foreground: var(--popover-foreground);
  --color-primary: var(--primary);
  --color-primary-foreground: var(--primary-foreground);
  --color-secondary: var(--secondary);
  --color-secondary-foreground: var(--secondary-foreground);
  --color-cta: var(--cta);
  --color-cta-foreground: var(--cta-foreground);
  --color-muted: var(--muted);
  --color-muted-foreground: var(--muted-foreground);
  --color-accent: var(--accent);
  --color-accent-foreground: var(--accent-foreground);
  --color-destructive: var(--destructive);
  --color-destructive-foreground: var(--destructive-foreground);
  --color-destructive-text: var(--destructive-text);
  --color-success: var(--success);
  --color-success-text: var(--success-text);
  --color-warning: var(--warning);
  --color-warning-text: var(--warning-text);
  --color-border: var(--border);
  --color-border-subtle: var(--border-subtle);
  --color-input: var(--input);
  --color-ring: var(--ring);

  /* NOTE: @theme cannot be class-scoped — these two easing overrides and the
     radius scale below are unavoidably global. They change Tailwind's default
     ease-out/ease-in-out and rounded-sm/md/lg/xl values app-wide. If your host
     app relies on Tailwind's defaults for those utilities, re-assert them after
     importing this file. */
  --ease-out: var(--ds-ease-out);
  --ease-in-out: var(--ds-ease-in-out);

  --animate-menu-in: ds-menu-in var(--ds-duration-enter) var(--ds-ease-out);
  --animate-menu-out: ds-menu-out var(--ds-duration-exit) var(--ds-ease-out) forwards;
  --animate-menu-in-reduced: ds-menu-in-reduced var(--ds-duration-exit) var(--ds-ease-out);
  --animate-menu-out-reduced: ds-menu-out-reduced var(--ds-duration-exit) var(--ds-ease-out) forwards;

  --animate-overlay-in: ds-fade-in var(--ds-duration-modal-enter) var(--ds-ease-out);
  --animate-overlay-out: ds-fade-out var(--ds-duration-modal-exit) var(--ds-ease-out) forwards;
  --animate-dialog-in: ds-menu-in var(--ds-duration-modal-enter) var(--ds-ease-out);
  --animate-dialog-out: ds-menu-out var(--ds-duration-modal-exit) var(--ds-ease-out) forwards;
  /* Reduced motion keeps the fade and drops the scale, at the exit duration. */
  --animate-dialog-in-reduced: ds-fade-in var(--ds-duration-modal-exit) var(--ds-ease-out);
  --animate-dialog-out-reduced: ds-fade-out var(--ds-duration-modal-exit) var(--ds-ease-out) forwards;

  --animate-sheet-in-right: ds-sheet-in-right var(--ds-duration-modal-enter) var(--ds-ease-out);
  --animate-sheet-out-right: ds-sheet-out-right var(--ds-duration-modal-exit) var(--ds-ease-out) forwards;
  --animate-sheet-in-left: ds-sheet-in-left var(--ds-duration-modal-enter) var(--ds-ease-out);
  --animate-sheet-out-left: ds-sheet-out-left var(--ds-duration-modal-exit) var(--ds-ease-out) forwards;
  --animate-sheet-in-top: ds-sheet-in-top var(--ds-duration-modal-enter) var(--ds-ease-out);
  --animate-sheet-out-top: ds-sheet-out-top var(--ds-duration-modal-exit) var(--ds-ease-out) forwards;
  --animate-sheet-in-bottom: ds-sheet-in-bottom var(--ds-duration-modal-enter) var(--ds-ease-out);
  --animate-sheet-out-bottom: ds-sheet-out-bottom var(--ds-duration-modal-exit) var(--ds-ease-out) forwards;

  --animate-accordion-down: ds-accordion-down var(--ds-duration-modal-enter) var(--ds-ease-out);
  --animate-accordion-up: ds-accordion-up var(--ds-duration-modal-exit) var(--ds-ease-out);

  --radius-sm: calc(var(--radius) - 4px);
  --radius-md: calc(var(--radius) - 2px);
  --radius-lg: var(--radius);
  --radius-xl: calc(var(--radius) + 4px);

  --text-label: var(--ds-text-label-sm);
}

/* Default border colour for the brand scope. Tailwind v4 leaves a bare `border`
   utility at `currentColor` (dark text), which paints harsh black hairlines on
   components that don't name a colour (e.g. Command's input divider). Anchor the
   default to the token; explicit `border-*` utilities sit in the utilities layer
   and still win. */
@layer base {
  .ds *,
  .ds *::before,
  .ds *::after {
    border-color: var(--border);
  }
}
